function questionFrom(drill: Drill, chapter: Chapter, number: number): Question {
  const id = `q-transversal-2026-${chapter.key}-${number}`
  return {
    id, moduleId: chapter.module, skillIds: chapter.skills,
    type: 'pjs', difficulty: number === 1 ? 4 : 5,
    case: drill.case, stem: drill.ask,
    options: [
      {id:'a', text:drill.errorA, rationale:drill.whyA},
      {id:'b', text:drill.best, rationale:drill.why},
      {id:'c', text:drill.errorB, rationale:drill.whyB}
    ],
    correctOptionId:'b',
    explanation:`${drill.why} La alternativa A no procede: ${drill.whyA} La alternativa C no procede: ${drill.whyB}`,
    sourceIds:chapter.sources,
    verifiedAt:'2026-10-12'
  }
}

export const dianAppliedPublicServiceQuestions: Question[] = chapters.flatMap(chapter => chapter.drills.map((drill, index) => questionFrom(drill, chapter, index + 1)))

